CREATE TABLE public.feature_settings (key text PRIMARY KEY, label text NOT NULL, enabled boolean NOT NULL DEFAULT true, updated_by uuid, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.feature_settings TO anon, authenticated; GRANT UPDATE ON public.feature_settings TO authenticated; GRANT ALL ON public.feature_settings TO service_role;
ALTER TABLE public.feature_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Feature availability" ON public.feature_settings FOR SELECT TO anon,authenticated USING(true);
CREATE POLICY "Admin feature changes" ON public.feature_settings FOR UPDATE TO authenticated USING(public.has_role(auth.uid(),'admin')) WITH CHECK(public.has_role(auth.uid(),'admin'));
INSERT INTO public.feature_settings(key,label) VALUES ('qbanks','Q-Banks'),('image_questions','Image-based questions'),('test_mode','Test mode'),('bookmarks','Bookmarks'),('mistake_vault','Mistake vault'),('daily_blitz','Daily Blitz'),('qotd','Question of the Day'),('reminders','Daily reminders'),('offline_downloads','Offline downloads'),('progress','Progress and statistics'),('reviews','Attempt reviews'),('checkout','Plan purchases');
CREATE TABLE public.purchase_journey (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles(id) ON DELETE CASCADE, stage text NOT NULL, plan_id text, months integer, platform text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.purchase_journey TO authenticated; GRANT ALL ON public.purchase_journey TO service_role;
ALTER TABLE public.purchase_journey ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrator journey read" ON public.purchase_journey FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
CREATE TABLE public.admin_audit (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), actor_id uuid, action text NOT NULL, entity text NOT NULL, record_key text NOT NULL, changed_fields jsonb NOT NULL DEFAULT '[]', created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.admin_audit TO authenticated; GRANT ALL ON public.admin_audit TO service_role;
ALTER TABLE public.admin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Administrator audit read" ON public.admin_audit FOR SELECT TO authenticated USING(public.has_role(auth.uid(),'admin'));
ALTER TABLE public.subscriptions ADD COLUMN amount_paid_paise integer, ADD COLUMN allocation_note text NOT NULL DEFAULT '';
CREATE OR REPLACE FUNCTION public.feature_enabled(_key text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT enabled FROM public.feature_settings WHERE key=_key),true) $$;
CREATE OR REPLACE FUNCTION public.console_audit() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE k text; fields jsonb; BEGIN IF TG_OP='UPDATE' THEN NEW.updated_at=now(); END IF; IF TG_TABLE_NAME='feature_settings' THEN NEW.updated_by=auth.uid(); END IF; IF TG_TABLE_NAME='subscriptions' AND (NEW.amount_paid_paise<0 OR length(NEW.allocation_note)>500) THEN RAISE EXCEPTION 'Invalid allocation amount or note'; END IF; IF TG_OP='INSERT' THEN SELECT jsonb_agg(key) INTO fields FROM jsonb_each(to_jsonb(NEW)); ELSE SELECT jsonb_agg(n.key) INTO fields FROM jsonb_each(to_jsonb(NEW)) n WHERE n.value IS DISTINCT FROM to_jsonb(OLD)->n.key AND n.key NOT IN ('updated_at','updated_by'); END IF; k:=coalesce(to_jsonb(NEW)->>'id',to_jsonb(NEW)->>'key',to_jsonb(NEW)->>'code',''); IF fields IS NOT NULL AND public.has_role(auth.uid(),'admin') THEN INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),lower(TG_OP),TG_TABLE_NAME,k,fields); END IF; RETURN NEW; END $$;
CREATE TRIGGER console_feature_audit BEFORE UPDATE ON public.feature_settings FOR EACH ROW EXECUTE FUNCTION public.console_audit();
CREATE TRIGGER console_subscription_audit BEFORE INSERT OR UPDATE ON public.subscriptions FOR EACH ROW EXECUTE FUNCTION public.console_audit();
CREATE TRIGGER console_plan_audit BEFORE UPDATE ON public.subscription_plans FOR EACH ROW EXECUTE FUNCTION public.console_audit();
CREATE TRIGGER console_profile_audit BEFORE UPDATE ON public.profiles FOR EACH ROW EXECUTE FUNCTION public.console_audit();
CREATE TRIGGER console_coupon_audit BEFORE INSERT OR UPDATE ON public.discount_coupons FOR EACH ROW EXECUTE FUNCTION public.console_audit();
CREATE OR REPLACE FUNCTION public.track_purchase_stage(_stage text,_plan text DEFAULT NULL,_months integer DEFAULT NULL,_platform text DEFAULT 'web') RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.device_session_active() THEN RAISE EXCEPTION 'Active sign-in required'; END IF; IF _stage NOT IN ('plans_viewed','coupon_page','payment_page','payment_opened','payment_cancelled','payment_failed','verification_pending') OR _platform NOT IN ('web','android') OR (_months IS NOT NULL AND _months NOT IN (12,24)) THEN RAISE EXCEPTION 'Invalid purchase stage'; END IF; IF _plan IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.subscription_plans WHERE id=_plan) THEN RAISE EXCEPTION 'Invalid plan'; END IF; IF NOT EXISTS(SELECT 1 FROM public.purchase_journey WHERE user_id=auth.uid() AND stage=_stage AND plan_id IS NOT DISTINCT FROM _plan AND months IS NOT DISTINCT FROM _months AND created_at>now()-interval '30 seconds') THEN INSERT INTO public.purchase_journey(user_id,stage,plan_id,months,platform) VALUES(auth.uid(),_stage,_plan,_months,_platform); END IF; END $$;
CREATE OR REPLACE FUNCTION public.admin_console_users(_search text DEFAULT '',_offset integer DEFAULT 0,_journeys boolean DEFAULT false) RETURNS TABLE(user_id uuid,email text,full_name text,study_year text,college text,phone text,latest_stage text,stage_at timestamptz,plan_id text,months integer,platform text,payment_status text) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; RETURN QUERY SELECT p.id,u.email::text,p.full_name,p.study_year,p.college,p.phone,j.stage,j.created_at,j.plan_id,j.months,j.platform,r.status FROM public.profiles p JOIN auth.users u ON u.id=p.id LEFT JOIN LATERAL (SELECT x.* FROM public.purchase_journey x WHERE x.user_id=p.id ORDER BY x.created_at DESC LIMIT 1) j ON true LEFT JOIN LATERAL (SELECT x.status FROM public.payment_requests x WHERE x.user_id=p.id ORDER BY x.created_at DESC LIMIT 1) r ON true WHERE concat(u.email,' ',p.full_name,' ',p.phone,' ',p.college) ILIKE '%'||left(_search,100)||'%' AND (NOT _journeys OR j.id IS NOT NULL) ORDER BY CASE WHEN _journeys THEN j.created_at ELSE p.created_at END DESC LIMIT 50 OFFSET greatest(_offset,0); END $$;
CREATE OR REPLACE FUNCTION public.admin_user_detail(_user uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE result jsonb; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; SELECT jsonb_build_object('profile',to_jsonb(p)-'avatar_url','email',u.email,'subscriptions',coalesce((SELECT jsonb_agg(x ORDER BY x.created_at DESC) FROM public.subscriptions x WHERE x.user_id=p.id),'[]'::jsonb),'payments',coalesce((SELECT jsonb_agg(x ORDER BY x.created_at DESC) FROM public.payment_requests x WHERE x.user_id=p.id),'[]'::jsonb),'journey',coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM public.purchase_journey WHERE user_id=p.id ORDER BY created_at DESC LIMIT 100) x),'[]'::jsonb),'devices',coalesce((SELECT jsonb_agg(x) FROM public.account_devices x WHERE x.user_id=p.id AND revoked_at IS NULL),'[]'::jsonb),'attempts',(SELECT count(*) FROM public.attempts x WHERE x.user_id=p.id),'correct',(SELECT count(*) FROM public.attempts x WHERE x.user_id=p.id AND x.correct),'bookmarks',(SELECT count(*) FROM public.bookmarks x WHERE x.user_id=p.id)) INTO result FROM public.profiles p JOIN auth.users u ON u.id=p.id WHERE p.id=_user; IF result IS NULL THEN RAISE EXCEPTION 'Student not found'; END IF; RETURN result; END $$;
CREATE OR REPLACE FUNCTION public.admin_save_student(_user uuid,_name text,_phone text,_year text,_college text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF length(btrim(_name))>150 OR length(_college)>150 OR (_phone<>'' AND _phone !~ '^\+[1-9][0-9]{9,14}$') OR _year NOT IN ('','MBBS - First year','MBBS - Second year','MBBS - Third year','MBBS - Fourth year','Housemanship/Internship','Post MBBS') THEN RAISE EXCEPTION 'Check the student details'; END IF; UPDATE public.profiles SET full_name=nullif(btrim(_name),''),phone=nullif(_phone,''),study_year=nullif(_year,''),college=nullif(btrim(_college),'') WHERE id=_user; IF NOT FOUND THEN RAISE EXCEPTION 'Student not found'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.admin_allocate_access(_user uuid,_plan text,_months integer,_start date,_amount integer,_note text DEFAULT '',_request uuid DEFAULT NULL) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE sid uuid; r public.payment_requests; BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _amount IS NULL OR _amount<0 OR length(_note)>500 THEN RAISE EXCEPTION 'Enter a valid amount and note'; END IF; IF _request IS NOT NULL THEN SELECT * INTO r FROM public.payment_requests WHERE id=_request FOR UPDATE; IF NOT FOUND OR r.user_id<>_user OR r.plan_id<>_plan OR r.status<>'pending' THEN RAISE EXCEPTION 'Payment request unavailable'; END IF; IF _amount<>r.total_paise THEN RAISE EXCEPTION 'Use the recorded payment amount when approving a request'; END IF; END IF; sid:=public.approve_subscription(_user,_plan,_months,_start,_request); UPDATE public.subscriptions SET amount_paid_paise=_amount,allocation_note=_note WHERE id=sid; RETURN sid; END $$;
CREATE OR REPLACE FUNCTION public.admin_update_access(_id uuid,_start date,_months integer,_amount integer,_note text,_revoked boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF _months NOT BETWEEN 1 AND 36 OR _start IS NULL OR _amount IS NULL OR _amount<0 OR length(_note)>500 THEN RAISE EXCEPTION 'Check duration, amount and note'; END IF; UPDATE public.subscriptions SET starts_at=_start::timestamptz,ends_at=_start::timestamptz+make_interval(months=>_months),amount_paid_paise=_amount,allocation_note=_note,revoked=_revoked WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Subscription not found'; END IF; END $$;
CREATE OR REPLACE FUNCTION public.admin_save_plan(_id text,_name text,_description text,_year integer,_two_year integer,_original_year integer,_original_two_year integer,_enabled boolean,_subjects text[]) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF length(btrim(_name)) NOT BETWEEN 2 AND 100 OR length(_description)>1000 OR _year IS NULL OR _two_year IS NULL OR _year<0 OR _two_year<0 OR _original_year<_year OR _original_two_year<_two_year OR coalesce(cardinality(_subjects),0)=0 OR EXISTS(SELECT 1 FROM unnest(_subjects) s WHERE NOT EXISTS(SELECT 1 FROM public.decks d WHERE d.subject=s AND depth=1)) THEN RAISE EXCEPTION 'Check plan prices and subject coverage'; END IF; UPDATE public.subscription_plans SET name=btrim(_name),description=btrim(_description),price_year=_year,price_two_year=_two_year,original_price_year=_original_year,original_price_two_year=_original_two_year,enabled=_enabled WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Plan not found'; END IF; DELETE FROM public.plan_subjects WHERE plan_id=_id; INSERT INTO public.plan_subjects(plan_id,subject) SELECT _id,s FROM (SELECT DISTINCT unnest(_subjects) s) x; INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),'update','plan_subjects',_id,'["subjects"]'); END $$;
CREATE OR REPLACE FUNCTION public.admin_all_plans() RETURNS SETOF public.subscription_plans LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; RETURN QUERY SELECT * FROM public.subscription_plans ORDER BY price_year; END $$;
CREATE OR REPLACE FUNCTION public.admin_bank_content(_subject text,_search text DEFAULT '',_offset integer DEFAULT 0) RETURNS SETOF public.questions LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; RETURN QUERY SELECT * FROM public.questions WHERE subject=_subject AND (id::text=left(_search,100) OR concat(deck_path,' ',stem) ILIKE '%'||left(_search,100)||'%') ORDER BY sort_key,id LIMIT 20 OFFSET greatest(_offset,0); END $$;
CREATE OR REPLACE FUNCTION public.admin_save_question(_id bigint,_stem text,_options jsonb,_answer text,_explanation text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Administrator access required'; END IF; IF length(btrim(_stem)) NOT BETWEEN 1 AND 100000 OR length(_explanation)>200000 OR jsonb_typeof(_options)<>'array' OR jsonb_array_length(_options)<2 OR jsonb_array_length(_options)>10 OR length(_answer)>100 THEN RAISE EXCEPTION 'Check question content and options'; END IF; UPDATE public.questions SET stem=_stem,options=_options,answer=_answer,explanation=_explanation WHERE id=_id; IF NOT FOUND THEN RAISE EXCEPTION 'Question not found'; END IF; INSERT INTO public.admin_audit(actor_id,action,entity,record_key,changed_fields) VALUES(auth.uid(),'update','questions',_id::text,'["stem","options","answer","explanation"]'); END $$;
CREATE OR REPLACE FUNCTION public.study_feature_guard() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ DECLARE k text; BEGIN k:=CASE TG_TABLE_NAME WHEN 'bookmarks' THEN 'bookmarks' WHEN 'blitz_results' THEN 'daily_blitz' WHEN 'quiz_reviews' THEN 'reviews' ELSE 'qbanks' END; IF NOT public.feature_enabled(k) AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'This feature is currently disabled'; END IF; IF TG_OP='DELETE' THEN RETURN OLD; END IF; RETURN NEW; END $$;
CREATE TRIGGER console_bookmarks_guard BEFORE INSERT OR DELETE ON public.bookmarks FOR EACH ROW EXECUTE FUNCTION public.study_feature_guard();
CREATE TRIGGER console_blitz_guard BEFORE INSERT ON public.blitz_results FOR EACH ROW EXECUTE FUNCTION public.study_feature_guard();
CREATE TRIGGER console_reviews_guard BEFORE INSERT ON public.quiz_reviews FOR EACH ROW EXECUTE FUNCTION public.study_feature_guard();
CREATE TRIGGER console_attempts_guard BEFORE INSERT ON public.attempts FOR EACH ROW EXECUTE FUNCTION public.study_feature_guard();
CREATE POLICY "Q-bank availability" ON public.questions AS RESTRICTIVE FOR SELECT TO anon,authenticated USING ((SELECT public.feature_enabled('qbanks')) OR (SELECT public.has_role(auth.uid(),'admin')));
CREATE OR REPLACE FUNCTION public.quote_plan(_plan text,_months integer,_coupon text DEFAULT '') RETURNS TABLE(total_paise integer,discount_percent integer) LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.subscription_plans; d integer:=0; amount integer; BEGIN IF auth.uid() IS NULL OR NOT public.device_session_active() THEN RAISE EXCEPTION 'Sign in on an active device to select a plan'; END IF; IF NOT public.feature_enabled('checkout') AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Plan purchases are currently disabled'; END IF; SELECT * INTO p FROM public.subscription_plans WHERE id=_plan AND enabled; IF NOT FOUND OR _months NOT IN (12,24) THEN RAISE EXCEPTION 'Choose a valid plan and duration'; END IF; IF btrim(_coupon)<>'' AND upper(btrim(_coupon))<>'NIRMAYACARE' THEN SELECT percent INTO d FROM public.discount_coupons WHERE code=upper(btrim(_coupon)) AND enabled; IF NOT FOUND THEN RAISE EXCEPTION 'Coupon unavailable'; END IF; END IF; amount:=CASE WHEN _months=12 THEN p.price_year ELSE p.price_two_year END; RETURN QUERY SELECT round(amount*(100-d)/100.0)::int,d; END $$;
REVOKE ALL ON FUNCTION public.track_purchase_stage(text,text,integer,text), public.admin_console_users(text,integer,boolean),public.admin_user_detail(uuid),public.admin_save_student(uuid,text,text,text,text),public.admin_allocate_access(uuid,text,integer,date,integer,text,uuid),public.admin_update_access(uuid,date,integer,integer,text,boolean),public.admin_save_plan(text,text,text,integer,integer,integer,integer,boolean,text[]),public.admin_all_plans(),public.admin_bank_content(text,text,integer),public.admin_save_question(bigint,text,jsonb,text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.track_purchase_stage(text,text,integer,text), public.admin_console_users(text,integer,boolean),public.admin_user_detail(uuid),public.admin_save_student(uuid,text,text,text,text),public.admin_allocate_access(uuid,text,integer,date,integer,text,uuid),public.admin_update_access(uuid,date,integer,integer,text,boolean),public.admin_save_plan(text,text,text,integer,integer,integer,integer,boolean,text[]),public.admin_all_plans(),public.admin_bank_content(text,text,integer),public.admin_save_question(bigint,text,jsonb,text,text) TO authenticated;
GRANT EXECUTE ON FUNCTION public.feature_enabled(text) TO anon,authenticated,service_role;